import { mkdir, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { dirname, join as joinPath, resolve as resolvePath } from "node:path";
import { buildDts } from "./dts-builder";

import type {
	DrizzleValidatorsOptions,
	GeneratedData,
	ResolvedPaths,
} from "./types";

/**
 * Marker on the first line of every file this plugin writes to the output
 * directory. The P2-10 reconciliation pass only deletes files carrying it,
 * so hand-written files the user placed in the same dir are never touched.
 */
export const GENERATED_HEADER =
	"// AUTO-GENERATED by drizzle-validators. Do not edit.";

/**
 * Removes per-table files left behind by a previous generation whose table
 * no longer exists (finding P2-10). Orphans keep old validation code live
 * (still reachable via a direct import path like `@/validators/posts`),
 * compiling and masking schema changes.
 *
 * Guard: only files whose first line matches the generated header are
 * candidates; anything else (user files sharing the directory) survives.
 */
async function reconcileStaleTableFiles(
	absoluteOutputDir: string,
	currentTableNames: ReadonlySet<string>,
): Promise<void> {
	let entries: string[];
	try {
		entries = await readdir(absoluteOutputDir);
	} catch {
		return;
	}
	for (const entry of entries) {
		// Only per-table module files are candidates — .d.ts declarations
		// (including virtual-drizzle-validators.d.ts) end in ".ts" too and must
		// never be treated as stale table outputs.
		if (!entry.endsWith(".ts") || entry.endsWith(".d.ts") || entry === "index.ts")
			continue;
		const base = entry.slice(0, -3);
		if (currentTableNames.has(base)) continue;
		const filePath = joinPath(absoluteOutputDir, entry);
		try {
			const content = await readFile(filePath, "utf8");
			if (content.startsWith(GENERATED_HEADER)) {
				await rm(filePath, { force: true });
			}
		} catch {
			// unreadable/inaccessible file — never delete what we can't verify
		}
	}
}

export async function writeGeneratedFiles(opts: {
	paths: ResolvedPaths;
	options: DrizzleValidatorsOptions;
	viteRoot: string;
	splitByTable: boolean;
	moduleId: string;
	data: GeneratedData;
}): Promise<void> {
	const { paths, options, viteRoot, splitByTable, moduleId, data } = opts;
	const { absoluteOutputPath, absoluteOutputDir, dtsPath } = paths;
	const target = data.target;

	// Shim dir derives from the moduleId so multi-instance setups (custom
	// moduleIds) don't clobber each other's declarations.
	const nodeTypesDir = joinPath(
		viteRoot,
		"node_modules",
		"@types",
		moduleId.replace(/[^a-zA-Z0-9-]/g, "-"),
	);

	// Clean up old internal output directory BEFORE any writes (finding
	// P2-17): previously the rm ran concurrently (same Promise.all) with the
	// writes, so an outputPath inside node_modules/.drizzle-validators raced
	// against itself — the walker deleted freshly-written children mid-write,
	// hard-failing generation with ENOENT. Sequencing it before the writes
	// (and skipping it when the output dir lives inside the internal dir)
	// makes the race impossible.
	if (typeof options.outputPath === "string") {
		const internalDir = resolvePath(
			viteRoot,
			"node_modules",
			".drizzle-validators",
		);
		const outputDirResolved = resolvePath(absoluteOutputDir);
		const outputInsideInternal =
			outputDirResolved === internalDir ||
			outputDirResolved.startsWith(internalDir + "/");
		if (!outputInsideInternal) {
			await rm(internalDir, { recursive: true, force: true }).catch(() => {});
		}
	}

	const fileWritePromises: Promise<void>[] = [];

	if (splitByTable) {
		// Ensure output directory exists
		await mkdir(absoluteOutputDir, { recursive: true });

		// Write individual per-table files
		for (const [tableName, tableData] of data.tableCodes.entries()) {
			const [insertCode, selectCode, updateCode] = tableData.codes;
			const [insertName, selectName, updateName] = tableData.exportNames;

			const perTableCode = [
				"// AUTO-GENERATED by drizzle-validators. Do not edit.",
				data.importStatement,
				...(data.refineExportStatement
					? [data.refineExportStatement]
					: []),
				"",
				`export const insertSchema = ${insertCode}`,
				`export const ${insertName} = insertSchema`,
				"",
				`export const selectSchema = ${selectCode}`,
				`export const ${selectName} = selectSchema`,
				"",
				`export const updateSchema = ${updateCode}`,
				`export const ${updateName} = updateSchema`,
				"",
			].join("\n");

			const tableFilePath = joinPath(absoluteOutputDir, `${tableName}.ts`);
			fileWritePromises.push(writeFile(tableFilePath, perTableCode));
		}

		// Write barrel index.ts
		// NOTE: per-table files export generic names (insertSchema/selectSchema/
		// updateSchema) alongside prefixed ones — `export *` would collide across
		// tables. Re-export only the unique prefixed names explicitly.
		const barrelLines = [
			"// AUTO-GENERATED by drizzle-validators. Do not edit.",
			...(data.refineExportStatement
				? [data.refineExportStatement]
				: []),
			"",
			...Array.from(data.tableCodes.entries()).flatMap(([tableName, tableData]) =>
				tableData.exportNames.map(
					(exportName) => `export { ${exportName} } from './${tableName}'`,
				),
			),
			"",
		];
		fileWritePromises.push(
			writeFile(absoluteOutputPath, barrelLines.join("\n")),
		);
	} else {
		// Single-file mode: write everything to one file
		fileWritePromises.push(
			mkdir(dirname(absoluteOutputPath), { recursive: true }).then(() =>
				writeFile(absoluteOutputPath, data.singleFileCode),
			),
		);
	}

	// Build .d.ts with correct relative paths for each output location.
	// The @types shim is the PRIMARY type surface: TypeScript auto-includes
	// node_modules/@types/**, so no project-tree declaration file is needed.
	const nodeTypesDtsPath = joinPath(nodeTypesDir, "index.d.ts");
	const nodeTypesDts = buildDts({
		dtsLocation: nodeTypesDtsPath,
		outputPath: absoluteOutputPath,
		outputDir: absoluteOutputDir,
		moduleId,
		target,
		splitByTable,
		refineDtsStatement: data.refineDtsStatement,
		data,
	});
	// Fallback location (project tree) — written only when the shim cannot
	// be written, or when the user opts in via emitRootDts.
	const primaryDts = buildDts({
		dtsLocation: dtsPath,
		outputPath: absoluteOutputPath,
		outputDir: absoluteOutputDir,
		moduleId,
		target,
		splitByTable,
		refineDtsStatement: data.refineDtsStatement,
		data,
	});

	let shimOkPromise: Promise<boolean> | undefined;
	const writeShim = () => {
		shimOkPromise ??= mkdir(nodeTypesDir, { recursive: true })
			.then(() => writeFile(nodeTypesDtsPath, nodeTypesDts))
			.then(
				() => true,
				() => false,
			);
		return shimOkPromise;
	};
	fileWritePromises.push(writeShim().then(() => {}));

	fileWritePromises.push(
		(async () => {
			const shimOk = await writeShim();
			if (shimOk && !options.emitRootDts) return;
			if (!shimOk && !options.emitRootDts) {
				// @types unwritable (read-only node_modules): fall back to the
				// project-tree declaration so types still work, with a warning.
				console.warn(
					`[drizzle-validators] could not write @types shim (${nodeTypesDtsPath}) — ` +
						`falling back to ${dtsPath}. Set emitRootDts to silence.`,
				);
			}
			await mkdir(dirname(dtsPath), { recursive: true });
			await writeFile(dtsPath, primaryDts);
		})(),
	);

	await Promise.all(fileWritePromises);

	// Reconcile stale per-table output files AFTER the writes have settled
	// (finding P2-10): the removed/renamed table's old file must not outlive
	// its source.
	if (splitByTable && typeof options.outputPath === "string") {
		await reconcileStaleTableFiles(
			absoluteOutputDir,
			new Set(data.tableCodes.keys()),
		).catch(() => {});
	}

	const isInternal = typeof options.outputPath !== "string";
	if (isInternal) {
		console.log(`[drizzle-validators] schemas generated (internal mode)`);
	} else if (splitByTable) {
		console.log(
			`[drizzle-validators] wrote ${data.tableCodes.size} tables to ${absoluteOutputDir}`,
		);
	} else {
		console.log(`[drizzle-validators] wrote ${absoluteOutputPath}`);
	}
}
